// Throwaway UI prototype: three structurally different home variants; all edits stay in memory.
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={today:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',recall:'M4 12a8 8 0 1 0 2-6 M4 3v5h5 M12 8v5l3 2',practice:'m8 6-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',evidence:'M5 3h14v18H5Z M8 8h8 M8 12h8 M8 16h5',career:'M4 7h16v14H4Z M8 7V3h8v4 M4 12h16 M10 12v3h4v-3',design:'M4 4h6v6H4Z M14 4h6v6h-6Z M4 14h6v6H4Z M14 14h6v6h-6Z'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.today}"/></svg>`;
const names={today:'今日',recall:'回忆练习',practice:'工程实践',evidence:'能力证据',career:'求职准备'};
const params=new URLSearchParams(location.search);
let state={page:'today',variant:['A','B','C'].includes(params.get('variant'))?params.get('variant'):'A',q:0,phase:'answer',answer:'',confidence:'不确定',hint:false,history:[],reviewed:false,filter:'全部',practiceTab:'任务',mode:'能力校准',evidence:[],interview:false,interviewAnswer:'',job:'',jobSaved:false};
const questions=[
{topic:'上下文与记忆',type:'机制解释',q:'对话记录已经落盘，为什么 Agent 下一轮仍可能“忘记”用户的要求？',hint:'沿着“保存 → 选择 → 组装 → 模型输入”检查信息经过了哪些边界。',points:['区分持久化的完整历史与本轮实际送入模型的上下文。','说明摘要、截断或检索选择会影响哪些信息进入请求。','通过请求快照与原始记录核对，定位信息在哪一步遗漏。'],transfer:'如果摘要丢掉了一条关键约束，你会在哪个位置观测，并用什么输入验证？'},
{topic:'工具与运行时',type:'场景辨析',q:'工具返回“库存不足”和工具执行进程意外退出，Agent 应该如何分别处理？',hint:'先区分业务结果和基础设施故障，再考虑模型看到的反馈与资源清理。',points:['区分可表达的业务失败与工具执行层的故障。','让调用方获得可判断的结果，避免吞掉异常或无限重试。','说明资源收尾、观测信息与是否重试取决于操作语义。'],transfer:'如果工具包含不可重复的写入操作，你会怎样调整重试判断？'},
{topic:'验证与调试',type:'验证设计',q:'一次取消操作后页面已显示结束，怎样证明后台任务也确实停止了？',hint:'UI 状态与实际执行资源是两条证据。你准备在哪里观察后者？',points:['区分 UI 状态变化、取消信号传递与实际执行停止。','选择可观察的进程、事件或资源释放证据。','检查迟到结果不会继续更新状态，并等待清理真正完成。'],transfer:'如果执行方暂时不响应取消，你如何表达当前状态与超时边界？'}
];
const btn=(label,action,cls='')=>`<button class="${cls}" data-action="${action}">${label}</button>`;
const leaf=`<svg class="leaf" viewBox="0 0 150 210" fill="none" aria-hidden="true"><path d="M72 198C75 140 88 87 119 16" stroke="#777f61" stroke-width="1.5"/><path d="M82 149C24 148 22 97 22 97c44 1 63 22 60 52ZM93 111c-8-49 26-67 45-71 4 34-14 63-45 71ZM109 69C75 58 72 26 80 9c27 14 33 33 29 60ZM73 185c-37-5-55-27-58-50 34-3 58 17 58 50Z" fill="#c0c7ae" stroke="#8f9c7d"/><path d="m23 100 57 46m57-102-42 63m-16-94 28 51m-89 76 52 40" stroke="#8f9c7d"/></svg>`;
function navigate(page){state.page=page;render();window.scrollTo(0,0)}
function notify(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3200)}
function header(title,desc,eyebrow='YOUR LEARNING, WITH EVIDENCE'){return `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1></div><div class="date">28<small>OCT · WED</small></div></div>`}
function render(){let remaining=3-state.history.length;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><svg class="brandmark" viewBox="0 0 32 32" fill="none"><path d="M5 24 16 6l11 18M10 18h12M16 6v24" stroke="currentColor" stroke-width="1.5"/></svg>知行</div><div class="brand-sub">AGENT LEARNING STUDIO</div><nav>${Object.entries(names).map(([k,v])=>`<button data-page="${k}" class="${state.page===k?'active':''}" ${state.page===k?'aria-current="page"':''}>${icon(k)}${v}${k==='recall'?`<span class="navcount">${remaining}</span>`:''}</button>`).join('')}</nav><div class="sidebottom"><div class="goalmini">我的方向<strong>Agent 开发工程师</strong></div><div class="avatar"><span>C</span><div>个人学习空间<br><small>只为自己的成长</small></div></div></div></aside><main class="main"><div class="topbar"><span>我的工作台 / ${names[state.page]}</span><div class="topright"><span class="quiet">演示日期 · 2026.10.28</span><span class="prototype">原型 · 刷新重置</span></div></div><div class="content viewfade">${({today:today,recall:recall,practice:practice,evidence:evidence,career:career,design:design})[state.page]()}</div></main></div>${state.page==='today'?`<div class="switcher">${btn('←','variant-prev')}<span><small>首页方案</small> ${state.variant} · ${{A:'回忆优先',B:'今日路径',C:'工程工作台'}[state.variant]}</span>${btn('→','variant-next')}</div>`:''}`;}
function hero(){return `<section class="card hero"><div class="herotext"><div class="eyebrow">DAILY RECALL</div><h2>${state.history.length===3?'想起来了，<br>接下来做出来。':'合上资料，<br>试着讲清楚。'}</h2><div class="hero-meta"><span>${3-state.history.length} 个场景</span><i></i><span>约 5 分钟</span></div>${btn(state.history.length===3?'进入实践 ↗':'开始回忆 →',state.history.length===3?'go-practice':'start-recall','primary')}</div>${leaf}</section>`}
function today(){if(state.variant==='B')return todayB();if(state.variant==='C')return todayC();return `${header('今天，从一次回忆开始。','','WEDNESDAY, OCTOBER 28')}<div class="grid homegrid"><div>${hero()}<div class="sectiontitle"><h3>继续实践</h3>${btn('打开工作台 ↗','go-practice','textbtn')}</div><section class="card practice-preview"><div class="taskicon">${icon('practice')}</div><div class="itemmain"><span class="quiet">建议任务</span><h2>工具调用的失败路径</h2><div class="taskstages"><span class="current">定义输入</span><b>—</b><span>实现</span><b>—</b><span>验证</span></div></div>${btn('↗','go-practice','arrow')}</section><div class="sectiontitle"><h3>最近证据</h3>${btn('查看全部 →','go-evidence','textbtn')}</div><div class="evidence-preview"><span class="evidence-check">✓</span><div class="itemmain"><strong>会话规则与恢复</strong><div class="quiet">10 月 27 日 · 功能通过 · 有代码帮助</div></div>${btn('→','go-evidence','arrow')}</div></div><aside><section class="card calendar-card"><div class="row"><h3 style="margin:0">本周</h3><span class="quiet">10.26 — 11.01</span></div><div class="weekstrip">${['一','二','三','四','五','六','日'].map((d,i)=>`<div class="${i===2?'currentday':''}"><small>${d}</small><strong>${[26,27,28,29,30,31,1][i]}</strong><i class="${i===2?'dotday':''}"></i></div>`).join('')}</div><div class="row" style="margin-top:23px"><h3 style="margin:0">待回忆</h3><span class="quiet">${3-state.history.length} / 3</span></div>${questions.map((q,i)=>`<div class="listitem"><span class="recallmark ${state.history.some(h=>h.i===i)?'complete':''}">${state.history.some(h=>h.i===i)?'✓':String(i+1).padStart(2,'0')}</span><div class="itemmain"><strong>${q.topic}</strong><p>${state.history.find(h=>h.i===i)?state.history.find(h=>h.i===i).days+' 天后再练':q.type}</p></div>${btn('→','start-recall','arrow')}</div>`).join('')}<div class="progress">${questions.map((_,i)=>`<i class="${state.history.find(h=>h.i===i)?'done':''}"></i>`).join('')}</div></section><section class="interview-preview"><div class="eyebrow">INTERVIEW PRACTICE</div><h2>把一个案例<br>讲给面试官听。</h2><div class="row"><span class="quiet">场景 · 决策 · 证据</span>${btn('开始 →','go-career','small')}</div></section></aside></div>`}
function todayB(){return `${header('把今天，安排成一条清晰的路。','先检索，再实践，最后带着证据收尾。计划可以调整。','TODAY / A LEARNING PATH')}<div class="card"><div class="row"><span class="chip green">建议节奏</span><span class="quiet">先做一步，再决定是否继续</span></div>${[['01','唤回旧知','3 个相关场景，先回答再核对。','开始回忆','start-recall'],['02','集中实践','带着一个待验证的问题，进入 VS Code。','查看实践','go-practice'],['03','整理证据','分别记录功能、解释和 AI 帮助。','整理证据','go-evidence'],['04','练习表达','把一个真实案例讲清楚，回应追问。','进入求职准备','go-career']].map(r=>`<div class="bigpath"><span class="itemnum">${r[0]}</span><div><h2 style="margin-bottom:5px">${r[1]}</h2><p>${r[2]}</p></div>${btn(r[3]+' →',r[4],r[0]==='01'?'primary':'')}</div>`).join('')}</div><div class="grid" style="margin-top:24px"><section class="card"><h3>今日时间预算</h3><div class="budget"><span></span><span></span><span></span><span></span></div><p class="quiet">原计划：主线 4h · 面试机制 1.5h · 编码 1h · 收尾 0.5h</p></section><section class="card darkpanel"><div class="eyebrow">NEXT SESSION</div><h2 style="margin-top:15px">下次，从这里继续。</h2>${btn('生成交接摘要 ↗','handoff')}</section></div>`}
function todayC(){return `${header('从一个问题，到一份工程证据。','让每次学习都能落到你能解释、能验证的具体行为。','WORKBENCH / LEARN BY BUILDING')}<div class="card darkpanel"><div class="row wrap"><div><div class="eyebrow">CURRENT INTENTION</div><h2 style="margin:12px 0">验证工具失败路径与资源收尾</h2><p style="margin:0">建议实践 · 能力校准 · 在 VS Code 中集中完成</p></div>${btn('打开实践工作台 ↗','go-practice')}</div></div><div class="board"><section class="boardcol"><div class="row"><h3 style="margin:0">先想清楚</h3><span class="quiet">01</span></div><article class="card"><span class="chip">检索练习</span><h3 style="margin-top:15px">这三个问题，你还能解释吗？</h3><p>上下文选择、工具失败、取消验证。</p>${btn('开始回忆 →','start-recall','textbtn')}</article><article class="card"><h3>界定这次的输入与结果</h3><p>先明确一个可判定的行为，再决定需要哪些代码。</p>${btn('查看任务 →','go-practice','textbtn')}</article></section><section class="boardcol"><div class="row"><h3 style="margin:0">集中做出来</h3><span class="quiet">02</span></div><article class="card"><span class="chip green">VS Code</span><h3 style="margin-top:15px">保留你的完整尝试</h3><p>按需要请求提示；直接索取实现也可以，记录实际帮助。</p>${btn('准备实践 →','go-practice','textbtn')}</article></section><section class="boardcol"><div class="row"><h3 style="margin:0">让结果有依据</h3><span class="quiet">03</span></div><article class="card"><span class="chip">历史记录</span><h3 style="margin-top:15px">会话规则：功能通过</h3><p>解释与迁移能力仍需各自的证据。</p>${btn('查看证据 →','go-evidence','textbtn')}</article><article class="card"><h3>转成面试中的一个案例</h3><p>场景问题 → 决策 → 验证 → 取舍。</p>${btn('练习表达 →','go-career','textbtn')}</article></section></div>`}
function recall(){const q=questions[state.q];if(state.history.length===3&&state.phase!=='feedback')return `${header('这一轮，留下了具体的反馈。','回忆结果用于安排复习；工程实现能力仍需实践验证。','RECALL / SESSION COMPLETE')}<div class="card"><div class="metric">3 / 3</div><h2 style="margin-top:18px">回忆练习已完成</h2>${state.history.map(h=>`<div class="listitem"><div class="itemmain"><strong>${questions[h.i].topic}</strong><p>${esc(h.rating)} · ${h.hint?'使用了提示':'未使用提示'} · 自评把握：${esc(h.confidence)}</p></div><span class="chip">${h.days} 天后再练</span></div>`).join('')}<div class="callout">现在选择一个与你实践有关的卡点。带着它写代码，观察行为是否符合预测。</div><div class="row">${btn('进入工程实践 →','go-practice','primary')}${btn('导出本轮记录','export')}</div></div>`;
return `${header('先从自己的脑海里，找答案。','先写下判断，再看核对要点。需要帮助时可以直接打开提示。','RECALL / RETRIEVE BEFORE REVIEW')}<div class="recallwrap"><div class="row"><span class="chip">${q.type} · ${q.topic}</span><span class="quiet">${state.history.length+1} / 3 · 演示题卡</span></div><div class="progress">${questions.map((_,i)=>`<i class="${i<state.history.length?'done':''}"></i>`).join('')}</div><h2 class="question">${q.q}</h2><label class="quiet" for="answer">我的解释与验证思路</label><textarea id="answer" class="writing" style="margin-top:10px" placeholder="用自己的话写下机制、一个具体例子，以及你会如何验证……" ${state.phase==='feedback'?'readonly':''}>${esc(state.answer)}</textarea>${state.phase==='answer'?`<div class="row wrap" style="margin-top:15px"><div class="inlineform"><label class="quiet" for="confidence">答前把握</label><select id="confidence">${['不确定','部分有把握','很有把握'].map(t=>`<option ${state.confidence===t?'selected':''}>${t}</option>`).join('')}</select></div>${btn(state.hint?'已使用提示':'给我一个提示','hint','textbtn')}</div>${state.hint?`<div class="callout">${q.hint}</div>`:''}<div class="row" style="margin-top:25px">${btn('暂时想不起来，直接学习','reveal-empty','textbtn')}${btn('提交并核对 →','reveal','primary')}</div>`:`<section class="feedback"><h3>核对思路，而不是匹配措辞</h3><p class="quiet">演示参考要点 · 由你自评，未调用 AI 自动判分</p><div class="checks">${q.points.map((p,i)=>`<label><input type="checkbox" data-point="${i}"><span>${p}</span></label>`).join('')}</div><p class="note" style="margin-bottom:0"><strong>再想一步：</strong>${q.transfer}</p></section><label class="quiet" for="correction">这次遗漏了什么？下一次提醒自己什么？</label><textarea id="correction" class="writing" style="min-height:85px;margin-top:8px" placeholder="记一个具体差异；不需要抄写参考答案。"></textarea><h3 style="margin-top:25px">根据这次表现，安排下一次</h3><div class="rating">${btn('<strong>还没想起来</strong><span>明天再试 · 先补足理解</span>','rate-1')}${btn('<strong>部分想起 / 用了提示</strong><span>3 天后 · 再试一次</span>','rate-3')}${btn('<strong>独立解释清楚</strong><span>7 天后 · 换个场景</span>','rate-7')}</div><p class="footnote">这是可调的演示间隔，不是记忆预测；看过答案后的流畅感不计为独立回忆。</p>`}</div>`}
const context='目标：Agent 开发求职。模式：能力校准。\n本次建议任务：选择一段熟悉的工具执行链路，验证业务失败、执行故障与收尾行为。\n请先协助明确输入、预期输出与观察点，不提前提供核心实现。\n我负责：分析、选验证输入、实现与解释；可按需请求提示或完整示范。\n验收记录需区分：功能结果、个人贡献、AI 帮助、解释与迁移证据。';
function practice(){return `${header('把理解，放进真实的执行过程。','在网页里明确目标，在 VS Code 中集中实现，回来核对证据。','PRACTICE / BUILD & VERIFY')}<div class="row wrap"><div class="tabs">${['任务','带到 VS Code','提交证据'].map(t=>`<button class="${state.practiceTab===t?'selected':''}" data-tab="${t}">${t}</button>`).join('')}</div><select id="mode" aria-label="实践模式">${['能力校准','实际交付'].map(t=>`<option ${state.mode===t?'selected':''}>${t}</option>`).join('')}</select></div>${state.practiceTab==='任务'?`<div class="grid"><section class="card"><span class="chip orange">建议任务</span><h2 style="margin-top:20px">验证工具执行的失败路径</h2><div class="sectiontitle"><h3>完成边界</h3></div><div class="pathstep"><span class="dot">1</span><div>定义可判断的输入与结果<p>区分业务失败、执行故障，选择实际支持的输入。</p></div></div><div class="pathstep"><span class="dot">2</span><div>实现并观察一次完整调用<p>保存请求、返回结果和收尾事件的对应关系。</p></div></div><div class="pathstep"><span class="dot">3</span><div>解释一个真实取舍<p>例如错误返回位置与调用方恢复方式的关系。</p></div></div>${btn('准备 VS Code 上下文 →','prepare','primary')}</section><aside class="card"><h3>${state.mode==='能力校准'?'我的任务':'分工'}</h3><p>${state.mode==='能力校准'?'需求分析、源码定位、方案与实现。卡住时再选择帮助范围。':'AI 可以参与完整实现；你参与关键决策、代码审查与验收。'}</p><h3>观察重点</h3><p>执行是否结束？资源是否释放？</p></aside></div>`:state.practiceTab==='带到 VS Code'?`<section class="card"><span class="chip green">手动交接</span><h2 style="margin-top:18px">带到 VS Code</h2><textarea id="context" class="writing">${esc(context.replace('模式：能力校准','模式：'+state.mode))}</textarea><div class="row" style="margin-top:20px">${btn('复制上下文','copy-context','primary')}${btn('我已实践，整理证据 →','submit-tab')}</div></section>`:`<section class="card"><h2>添加实践证据</h2><div class="field"><label for="ev-title">任务 / 行为</label><input id="ev-title" placeholder="例如：工具失败后的资源收尾"></div><div class="field"><label for="ev-result">运行证据 · 命令 / 结果 / 时间 / 版本</label><textarea id="ev-result" class="writing" style="min-height:100px" placeholder="粘贴实际输出或证据文件路径；未运行请写未验证。"></textarea></div><div class="grid"><div class="field"><label for="ev-own">我自己完成的部分</label><textarea id="ev-own" class="writing" style="min-height:100px"></textarea></div><div class="field"><label for="ev-help">AI 提供的帮助</label><textarea id="ev-help" class="writing" style="min-height:100px" placeholder="具体提示、局部代码、完整实现或测试等"></textarea></div></div>${btn('保存为待审证据 →','save-evidence','primary')}</section>`}`}
function evidence(){const rows=[['会话规则与恢复','功能通过','具体代码帮助','完整解释待验证','变式待验证','10.27 · 实验 08'],['进程取消与收尾','功能通过','AI 接线与验证','部分机制有记录','独立迁移待验证','实验 06'],['上下文与摘要边界','未作实现结论','讨论证据','有边界解释证据','变式实现待验证','学习状态摘要'],['工具审批与取消','待验收','用户实现 + AI 审查','待补充','待验证','实验 07']];return `${header('能力，应该有可追溯的依据。','功能通过、解释清楚、独立实现与迁移成功，分别记录。','EVIDENCE / WHAT YOU CAN DEMONSTRATE')}<div class="three"><section class="card"><span class="eyebrow">IMPLEMENTATION</span><h2 style="margin-top:12px">做出来</h2><p class="note">输入、行为、结果与文件版本<br>功能通过 ≠ 独立完成</p></section><section class="card"><span class="eyebrow">EXPLANATION</span><h2 style="margin-top:12px">讲清楚</h2><p class="note">机制、取舍与边界<br>讨论证据也值得保留</p></section><section class="card"><span class="eyebrow">TRANSFER</span><h2 style="margin-top:12px">换场景仍能做</h2><p class="note">有意义的约束变化与验证<br>口头变式 ≠ 实现迁移</p></section></div><div class="sectiontitle"><h3>已有证据</h3><span class="quiet">来源：learning-state.md · 2026.10.27</span></div><section class="card scrolltable"><table class="matrix"><thead><tr><th>能力场景</th><th>功能结果</th><th>协助边界</th><th>解释</th><th>迁移</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${r[0]}</strong><br><span class="quiet">${r[5]}</span></td><td><span class="chip ${r[1]==='功能通过'?'green':''}">${r[1]}</span></td><td>${r[2]}</td><td>${r[3]}</td><td>${r[4]}</td></tr>`).join('')}</tbody></table></section><div class="sectiontitle"><h3>本轮证据草稿</h3>${btn('添加实践证据 →','submit-tab','textbtn')}</div>${state.evidence.length?state.evidence.map(e=>`<section class="card" style="margin-bottom:16px"><div class="row"><h3>${esc(e.title)}</h3><span class="chip orange">待审 · ${esc(e.mode)}</span></div><p class="sourcebox">${esc(e.result)}</p><p class="note">个人贡献：${esc(e.own||'未填写')}<br>AI 帮助：${esc(e.help||'未填写，待核对')}</p></section>`).join(''):`<section class="card"><div class="empty"><h3>还没有新证据</h3>${btn('添加一次实践 →','submit-tab','primary')}</div></section>`}${state.history.length?`<section class="card" style="margin-top:18px"><h3>本轮回忆 · 自评记录</h3><p>已完成 ${state.history.length} 项；未据此修改上方实现能力。</p>${btn('导出本轮记录','export','small')}</section>`:''}`}
function career(){return `${header('把真实能力，带到面试现场。','用岗位要求选择练习，用具体案例解释你的贡献。','CAREER / TOWARD AN AGENT ROLE')}<div class="grid"><div><section class="card"><div class="row"><h3>我的目标岗位</h3><span class="chip">目标岗位</span></div><h2 style="margin-top:18px">Agent 开发工程师</h2><div class="field"><label for="job">岗位要求</label><textarea id="job" class="writing" style="min-height:120px" placeholder="例如：你正在考虑的岗位 JD；原型仅保存草稿，不做自动匹配评分。">${esc(state.job)}</textarea></div>${btn(state.jobSaved?'更新岗位草稿':'保存岗位草稿','save-job','small')}</section><section class="card" style="margin-top:24px"><span class="chip">案例表达 · 会话规则与恢复</span><h2 style="margin-top:17px">讲清一次真实的工程决策。</h2>${state.interview?`<div class="callout">请讲一个案例：用户遇到了什么问题？你做了哪些决策？如何验证？哪些部分获得了 AI 帮助？</div><label class="quiet" for="interview">我的回答</label><textarea id="interview" class="writing">${esc(state.interviewAnswer)}</textarea><details><summary>查看自检与追问</summary><p class="note">是否描述具体触发场景？是否说明真实运行证据？是否准确区分个人贡献与 AI 帮助？</p><p>追问：如果新会话没有恢复出规则，你会沿哪条数据流定位？</p></details><div style="margin-top:18px">${btn('保存表达草稿','save-interview','primary')}</div>`:btn('开始一次案例表达 →','interview','primary')}</section></div><aside><section class="card darkpanel"><div class="eyebrow">A PORTFOLIO OF EVIDENCE</div><h2 style="margin-top:15px">一个场景。<br>一份证据。<br>你的贡献。</h2></section><section class="card" style="margin-top:24px"><h3>准备路径</h3><div class="timeline"><article><strong>确认岗位要求</strong><p class="quiet">明确要验证什么</p></article><article><strong>选择已有案例</strong><p class="quiet">对照个人贡献与证据</p></article><article><strong>练习追问与变式</strong><p class="quiet">暴露缺口，带回学习队列</p></article><article><strong>记录真实面试反馈</strong><p class="quiet">作为下一轮选题依据</p></article></div></section></aside></div>`}
function design(){return `${header('知行：为求职而学，为独立开发而练。','一个人的 Agent 学习工作台，连接学习方法、工程证据与求职反馈。','PRODUCT / DESIGN NOTES')}<section class="card darkpanel"><div class="eyebrow">THE CORE LOOP</div><h2 style="margin-top:16px">目标 → 回忆 → 实践 → 验证 → 复习与迁移 → 面试反馈</h2><p style="margin:0">每天只突出最值得开始的一步；用真实反馈调整后续任务。</p></section><div class="three" style="margin-top:24px"><section class="card"><h2>先尝试，再核对</h2><p>作答区优先，参考答案默认折叠；允许直接求助，记录实际提示范围。</p></section><section class="card"><h2>跨天再遇见</h2><p>按自评与帮助程度调整复习间隔。到期队列可以缩减与延期，不积累惩罚。</p></section><section class="card"><h2>在相近场景中辨析</h2><p>混合机制解释、方案判断与验证设计；不打断集中编码，不随机切换无关主题。</p></section></div><section class="card" style="margin-top:24px"><h2>网页与 VS Code 的分工</h2><div class="grid"><div><h3>网页</h3><p>今日行动、回忆与反馈、复习安排、证据审查、案例表达。</p></div><div><h3>VS Code + Agent</h3><p>源码阅读、完整实现、运行调试与验证。通过上下文摘要与证据交接。</p></div></div><div class="callout">后续连接本地工作区时，展示来源、版本与变更差异，再合并学习记录。原型没有编辑器连接或自动验收。</div></section><section class="card" style="margin-top:24px"><h2>原型范围与科学依据</h2><p>已实现：三种首页、回忆与核对、自评复习安排、实践交接、证据草稿、岗位与表达草稿、JSON 导出。数据仅存在当前页面内存，刷新重置。</p><p>真实记录仅用于历史证据摘要；回忆题、日期、队列与建议实践为演示。没有模型调用、自动能力评分、后台调度或文件同步。</p><p class="sources">检索练习与分散练习具有较广泛的研究支持；交叉练习需考虑任务条件。产品中的 1 / 3 / 7 天是待验证的初始规则，不是通用最优间隔。<a href="https://journals.sagepub.com/stoken/rbtfl/Z10jaVH/60XQM/full" target="_blank" rel="noreferrer">Dunlosky 等（2013），学习技术综述 ↗</a></p><p class="quiet">设计不使用连续打卡惩罚、学习时长排名或未经证据支持的掌握百分比。</p>${btn('导出本轮原型数据','export')}${btn('回到今日，对比首页方案 →','go-today','textbtn')}</section>`}
async function copyText(text){try{await navigator.clipboard.writeText(text);notify('已复制，可粘贴到 VS Code 对话')}catch{notify('浏览器未允许复制，请选中文本手动复制')}}
function exportData(){const blob=new Blob([JSON.stringify({prototype:true,exportedAt:new Date().toISOString(),recall:state.history,evidence:state.evidence,job:state.job,interview:state.interviewAnswer},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='知行-原型学习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function variant(delta){const all=['A','B','C'];state.variant=all[(all.indexOf(state.variant)+delta+3)%3];const u=new URL(location.href);u.searchParams.set('variant',state.variant);history.replaceState(null,'',u);render()}
function startRecall(){if(state.history.length<3){state.q=questions.findIndex((_,i)=>!state.history.some(h=>h.i===i));}navigate('recall')}
document.addEventListener('input',e=>{if(e.target.id==='answer')state.answer=e.target.value;if(e.target.id==='interview')state.interviewAnswer=e.target.value;if(e.target.id==='job'){state.job=e.target.value;state.jobSaved=false}});
document.addEventListener('change',e=>{if(e.target.id==='confidence')state.confidence=e.target.value;if(e.target.id==='mode'){state.mode=e.target.value;render()}});
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.page){navigate(el.dataset.page);return}if(el.dataset.tab){state.practiceTab=el.dataset.tab;render();return}const a=el.dataset.action;if(!a)return;if(a.startsWith('go-')){navigate(a.slice(3));return}if(a==='variant-prev')return variant(-1);if(a==='variant-next')return variant(1);if(a==='start-recall')return startRecall();if(a==='hint'){state.hint=true;render();return}if(a==='reveal'||a==='reveal-empty'){if(a==='reveal'&&!state.answer.trim()){notify('先写下你的思路，或选择“暂时想不起来”');return}state.phase='feedback';render();return}if(a.startsWith('rate-')){let days=Number(a.slice(5));if((state.hint||!state.answer.trim())&&days===7){notify('本次使用了提示或直接学习，请选择较短间隔再次独立尝试');return}state.history.push({i:state.q,question:questions[state.q].q,answer:state.answer,confidence:state.confidence,hint:state.hint,correction:$('#correction').value,checked:[...document.querySelectorAll('[data-point]:checked')].map(x=>Number(x.dataset.point)),days,rating:days===1?'还没想起来':days===3?'部分想起 / 用了提示':'独立解释清楚',recordedAt:new Date().toISOString()});state.answer='';state.phase='answer';state.hint=false;state.confidence='不确定';state.q=questions.findIndex((_,i)=>!state.history.some(h=>h.i===i));if(state.q<0)state.q=0;render();window.scrollTo(0,0);notify('已安排 '+days+' 天后复习（本轮演示）');return}if(a==='prepare'){state.practiceTab='带到 VS Code';render();return}if(a==='copy-context')return copyText($('#context').value);if(a==='submit-tab'){state.practiceTab='提交证据';navigate('practice');return}if(a==='save-evidence'){let title=$('#ev-title').value.trim(),result=$('#ev-result').value.trim();if(!title||!result){notify('请填写任务与实际运行证据；未运行可写“未验证”');return}state.evidence.push({title,result,own:$('#ev-own').value,help:$('#ev-help').value,mode:state.mode,status:'待审',time:new Date().toISOString()});navigate('evidence');notify('已保存待审草稿，未改变能力结论');return}if(a==='save-job'){if(!state.job.trim()){notify('先粘贴一段目标岗位要求');return}state.jobSaved=true;notify('岗位草稿已保留在本轮原型中');render();return}if(a==='interview'){state.interview=true;render();return}if(a==='save-interview'){if(!state.interviewAnswer.trim()){notify('先写下你的案例表达');return}notify('表达草稿已保存；尚未作能力评定');return}if(a==='export')return exportData();if(a==='handoff'){state.practiceTab='带到 VS Code';navigate('practice');$('#context').value=`本轮回忆：${state.history.length} / 3 项。\n待审证据：${state.evidence.length} 条。\n下一步：选择一个具体工程问题，明确输入、预期结果与观察点。\n${context}`;return}});
document.addEventListener('keydown',e=>{if(state.page!=='today'||e.target.closest('input,textarea,select,[contenteditable]'))return;if(e.key==='ArrowLeft'){e.preventDefault();variant(-1)}if(e.key==='ArrowRight'){e.preventDefault();variant(1)}});render();
